function methodCase(id, body, method, excluded = []) {
  return {
    id, layout: 'synthetic adversarial method boundary',
    reason: 'Pair rejection evidence with preservation of legitimate instructions.',
    raw: 'Onion bowl\nIngredients\n2 onions\n1 tbsp oil\nMethod\n' + body,
    expected: { name: 'Onion bowl', ingredients: ['2 onions', '1 tbsp oil'], method }, excluded,
  }
}

